-- ---------------------------------------------------------------------
-- Migration 0006_honesty
-- ---------------------------------------------------------------------
-- SMART Circle v2: teach only what each student's school has taught.
-- Who reported coverage, students' own reports, per-student early access, and why each view was allowed.

ALTER TABLE topic_coverage
    ADD COLUMN source VARCHAR(20) NOT NULL DEFAULT 'partner' COMMENT 'partner | tutor (after a phone call)' AFTER status;

ALTER TABLE schools
    ADD COLUMN coverage_checked_at DATETIME NULL COMMENT 'Partner confirmed "nothing changed since my last report"';

CREATE TABLE student_topic_reports (
    user_id     INT UNSIGNED NOT NULL,
    topic_id    INT UNSIGNED NOT NULL,
    status      VARCHAR(20)  NOT NULL COMMENT 'covered (my class has) | not_yet (my class has not, overrides the school)',
    review      VARCHAR(20)  NULL COMMENT 'NULL = not checked | confirmed | rejected (tutor)',
    reviewed_by INT UNSIGNED NULL,
    reviewed_at DATETIME     NULL,
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, topic_id),
    KEY idx_student_topic_reports_review (status, review),
    CONSTRAINT fk_student_topic_reports_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_student_topic_reports_topic FOREIGN KEY (topic_id) REFERENCES topics (id) ON DELETE CASCADE,
    CONSTRAINT fk_student_topic_reports_reviewed_by FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE topic_exceptions (
    user_id    INT UNSIGNED NOT NULL,
    topic_id   INT UNSIGNED NOT NULL,
    reason     TEXT         NOT NULL COMMENT 'Why the student needs it before the school teaches it',
    status     VARCHAR(20)  NOT NULL DEFAULT 'pending' COMMENT 'pending | approved | declined',
    decided_by INT UNSIGNED NULL,
    decided_at DATETIME     NULL,
    created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, topic_id),
    KEY idx_topic_exceptions_status (status, created_at),
    CONSTRAINT fk_topic_exceptions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_topic_exceptions_topic FOREIGN KEY (topic_id) REFERENCES topics (id) ON DELETE CASCADE,
    CONSTRAINT fk_topic_exceptions_decided_by FOREIGN KEY (decided_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE lesson_views
    ADD COLUMN access_basis VARCHAR(20) NULL COMMENT 'school | self | exception: why the student could watch' AFTER completed_at;

-- ---------------------------------------------------------------------
-- Migration 0007_assessments
-- ---------------------------------------------------------------------
-- SMART Circle v2: exams and assignments.
-- Server-side exam timer and when students may see their marks.

ALTER TABLE assessments
    ADD COLUMN results_at DATETIME NULL COMMENT 'When the tutor released marks to students (NULL = not yet)' AFTER status;

ALTER TABLE submissions
    ADD COLUMN deadline_at DATETIME NULL COMMENT 'Timed exams: started_at + duration; answers after this (plus grace) are refused' AFTER started_at;

-- ---------------------------------------------------------------------
-- Migration 0008_identity
-- ---------------------------------------------------------------------
-- SMART Circle v2: who our students are, and the pledge they make.
-- Application questionnaire answers, sign-up details (incl. evening classes), signed pledges.

ALTER TABLE applications
    ADD COLUMN answers TEXT NULL COMMENT 'JSON: questionnaire (reasons for schooling, career, habits, scenarios...)' AFTER motivation;

ALTER TABLE student_profiles
    ADD COLUMN study_mode  VARCHAR(20) NULL COMMENT 'day | boarder | self_boarder | evening' AFTER school_id,
    ADD COLUMN school_area VARCHAR(120) NULL COMMENT 'Area / trading centre / TA of the school' AFTER study_mode,
    ADD COLUMN travel_time VARCHAR(20) NULL COMMENT 'Day/evening students: time to reach school' AFTER school_area,
    ADD COLUMN home_study  VARCHAR(20) NULL COMMENT 'Study time available outside class' AFTER travel_time;

CREATE TABLE pledges (
    id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id       INT UNSIGNED NOT NULL,
    version       VARCHAR(20)  NOT NULL COMMENT 'Pledge wording version, e.g. 2026-1',
    period        VARCHAR(40)  NULL COMMENT 'Term it covers (set once the academic calendar exists)',
    statements    TEXT         NOT NULL COMMENT 'JSON snapshot of the vows as shown',
    signed_name   VARCHAR(150) NOT NULL COMMENT 'Name the student typed as a signature',
    guardian_name VARCHAR(150) NULL COMMENT 'Guardian who knows about the pledge',
    document_code VARCHAR(20)  NULL COMMENT 'Printable certificate (issued_documents.code)',
    ip            VARCHAR(45)  NOT NULL DEFAULT '',
    accepted_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_pledges_user (user_id, accepted_at),
    CONSTRAINT fk_pledges_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- Migration 0009_notes
-- ---------------------------------------------------------------------
-- SMART Circle v2: notes and slides with checkpoint exercises, encouraging feedback, re-checks.

CREATE TABLE notes (
    id         INT UNSIGNED     NOT NULL AUTO_INCREMENT,
    kind       VARCHAR(20)      NOT NULL DEFAULT 'notes' COMMENT 'notes | slides',
    title      VARCHAR(200)     NOT NULL,
    form       TINYINT UNSIGNED NOT NULL,
    subject    VARCHAR(20)      NOT NULL,
    topic_id   INT UNSIGNED     NOT NULL COMMENT 'Honesty rule: opens when the student''s school has taught it',
    summary    TEXT             NULL,
    status     VARCHAR(20)      NOT NULL DEFAULT 'draft' COMMENT 'draft | published',
    created_by INT UNSIGNED     NULL,
    created_at DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME         NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_notes_form (form, subject, status),
    CONSTRAINT fk_notes_topic FOREIGN KEY (topic_id) REFERENCES topics (id),
    CONSTRAINT fk_notes_created_by FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE note_blocks (
    id            INT UNSIGNED  NOT NULL AUTO_INCREMENT,
    note_id       INT UNSIGNED  NOT NULL,
    sort_order    SMALLINT      NOT NULL DEFAULT 0,
    type          VARCHAR(20)   NOT NULL COMMENT 'text | image | checkpoint',
    body          MEDIUMTEXT    NULL COMMENT 'text: simple markup; image: caption',
    image_path    VARCHAR(255)  NULL COMMENT 'In storage/, served only through the access check',
    assessment_id INT UNSIGNED  NULL COMMENT 'checkpoint: the exercise (assessments.kind = note_check)',
    is_final      TINYINT(1)    NOT NULL DEFAULT 0 COMMENT 'End-of-unit exercise',
    PRIMARY KEY (id),
    KEY idx_note_blocks_note (note_id, sort_order),
    CONSTRAINT fk_note_blocks_note FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE,
    CONSTRAINT fk_note_blocks_assessment FOREIGN KEY (assessment_id) REFERENCES assessments (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE assessments
    ADD COLUMN note_id INT UNSIGNED NULL COMMENT 'Checkpoint exercises inside notes' AFTER lesson_id,
    ADD KEY idx_assessments_note (note_id),
    ADD CONSTRAINT fk_assessments_note FOREIGN KEY (note_id) REFERENCES notes (id) ON DELETE CASCADE;

-- Encouraging feedback: what went well, where it went off track, and the next step.
ALTER TABLE submission_answers
    ADD COLUMN did_well  TEXT NULL AFTER feedback,
    ADD COLUMN off_track TEXT NULL AFTER did_well,
    ADD COLUMN next_step TEXT NULL AFTER off_track;

CREATE TABLE recheck_requests (
    id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    submission_id INT UNSIGNED NOT NULL,
    question_id   INT UNSIGNED NOT NULL,
    user_id       INT UNSIGNED NOT NULL,
    reason        TEXT         NOT NULL COMMENT 'Why the student believes the answer deserves more marks',
    status        VARCHAR(20)  NOT NULL DEFAULT 'open' COMMENT 'open | upheld | changed',
    old_score     DECIMAL(6,2) NULL,
    new_score     DECIMAL(6,2) NULL,
    tutor_reply   TEXT         NULL,
    resolved_by   INT UNSIGNED NULL,
    resolved_at   DATETIME     NULL,
    created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_recheck_status (status, created_at),
    KEY idx_recheck_submission (submission_id, question_id),
    CONSTRAINT fk_recheck_submission FOREIGN KEY (submission_id) REFERENCES submissions (id) ON DELETE CASCADE,
    CONSTRAINT fk_recheck_question FOREIGN KEY (question_id) REFERENCES questions (id) ON DELETE CASCADE,
    CONSTRAINT fk_recheck_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_recheck_resolved_by FOREIGN KEY (resolved_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- Migration 0010_calendar_grades
-- ---------------------------------------------------------------------
-- SMART Circle v2: the academic calendar (measurable terms), grades and term reports.

CREATE TABLE academic_years (
    id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    name       VARCHAR(20)  NOT NULL COMMENT 'e.g. 2026/27',
    starts_on  DATE         NOT NULL,
    ends_on    DATE         NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_academic_years_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE terms (
    id        INT UNSIGNED     NOT NULL AUTO_INCREMENT,
    year_id   INT UNSIGNED     NOT NULL,
    number    TINYINT UNSIGNED NOT NULL COMMENT '1-3',
    opens_on  DATE             NOT NULL,
    closes_on DATE             NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_terms (year_id, number),
    KEY idx_terms_dates (opens_on, closes_on),
    CONSTRAINT fk_terms_year FOREIGN KEY (year_id) REFERENCES academic_years (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE calendar_events (
    id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
    school_id  INT UNSIGNED NULL COMMENT 'NULL = national (Ministry / MANEB); otherwise one school''s own dates',
    kind       VARCHAR(20)  NOT NULL COMMENT 'jce | msce | midterm | mock | school_exam | holiday | other',
    title      VARCHAR(150) NOT NULL,
    starts_on  DATE         NOT NULL,
    ends_on    DATE         NOT NULL,
    forms      VARCHAR(20)  NULL COMMENT 'Comma list of forms it concerns, NULL = all',
    created_by INT UNSIGNED NULL,
    created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_calendar_events_dates (starts_on, ends_on),
    KEY idx_calendar_events_school (school_id),
    CONSTRAINT fk_calendar_events_school FOREIGN KEY (school_id) REFERENCES schools (id) ON DELETE CASCADE,
    CONSTRAINT fk_calendar_events_created_by FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE grade_bands (
    scale       VARCHAR(10)      NOT NULL COMMENT 'jce (Forms 1-2, letters) | msce (Forms 3-4, points)',
    grade       VARCHAR(5)       NOT NULL,
    min_percent TINYINT UNSIGNED NOT NULL,
    descriptor  VARCHAR(40)      NOT NULL,
    PRIMARY KEY (scale, grade)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE term_reports (
    id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id       INT UNSIGNED NOT NULL,
    term_id       INT UNSIGNED NOT NULL,
    data          MEDIUMTEXT   NOT NULL COMMENT 'JSON snapshot: subjects, categories, grades, comment',
    comment       TEXT         NULL COMMENT 'Tutor''s overall comment',
    document_code VARCHAR(20)  NULL COMMENT 'Printable, verifiable report (issued_documents.code)',
    issued_by     INT UNSIGNED NULL,
    issued_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_term_reports (user_id, term_id),
    CONSTRAINT fk_term_reports_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_term_reports_term FOREIGN KEY (term_id) REFERENCES terms (id) ON DELETE CASCADE,
    CONSTRAINT fk_term_reports_issued_by FOREIGN KEY (issued_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

